/bin/zsh -lc "python3 - <<'PY'
import zipfile,xml.etree.ElementTree as E
p='hakusho_R07_5-3-10.xlsx'; n={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
with zipfile.ZipFile(p) as z:
 ss=[''.join(x.itertext()) for x in E.fromstring(z.read('xl/sharedStrings.xml')).findall('m:si',n)]
 print(z.read('xl/workbook.xml').decode())
 for f in z.namelist():
  if f.startswith('xl/worksheets/sheet') and f.endswith('.xml'):
   print(f)
   for r in E.fromstring(z.read(f)).findall('.//m:row',n):
    out=[]
    for c in r:
     v=c.find('m:v',n)
     if v is not None: out.append(c.attrib['r']+'='+ (ss[int(v.text)] if c.get('t')=='s' else v.text))
    if out: print(' | '.join(out))
PY"

