from pathlib import Path
queries={'yakubutsu_kyosei_report':['表８','21 新実施','５ おわりに','23 新','再犯の有無'], 'yakubutsu_hogo_report':['表１ 調査','(a)性別','表３ 全再犯','表４ 薬物','表５ コア','表ア    傾向','事件種別の偏り'], 'boryoku_report':['表１－３ プログラム','表３－２ 児童','11 名を調査','児童虐待防止版導入前','なお、児童虐待防止版受講者']}
for f,qs in queries.items():
